"""DEV-only offline HTML export. No external requests, writes or production changes."""
import base64
import html
import json
from pathlib import Path


_LOGO_BASE64 = ''

def _esc(value):
    return html.escape(str(value if value is not None else ''), quote=True)


def _price(value):
    try:
        return f'{float(value):,.2f}'.replace(',', ' ').replace('.', ',') + ' zł'
    except (ValueError, TypeError):
        return 'Do ustalenia'


def generate_offer_html(offer: dict, logo_path: str = '') -> bytes:
    """Generate a standalone, offline HTML preview from an existing completed offer."""
    data = offer.get('dane_oferty') or {}
    if isinstance(data, str):
        try:
            data = json.loads(data)
        except (ValueError, TypeError):
            data = {}
    mode = offer.get('tryb') or data.get('tryb') or ('B2B' if data.get('firma') else 'B2C')
    client = data.get('firma') or offer.get('klient') or data.get('klient') or 'Klient'
    car = offer.get('auto') or data.get('pojazd_opis') or (str(data.get('final_brand',''))+' '+str(data.get('final_model',''))).strip()
    service = offer.get('pakiet') or data.get('pakiet') or data.get('zakres_b2b') or 'Oferta indywidualna'
    intro = data.get('wstep') or ''
    number = offer.get('nr_o') or data.get('nr_o') or 'Wersja testowa'
    price = _price(offer.get('cena'))
    tax = 'netto' if mode == 'B2B' else '— potwierdź VAT / brutto przed wysyłką'
    addons = data.get('dodatki') or []
    if not isinstance(addons, list):
        addons = []
    additions = ''.join(f'<li>{_esc(x)}</li>' for x in addons) or '<li>Zakres szczegółowy zgodnie z zatwierdzoną kalkulacją.</li>'
    image = ''
    if logo_path and Path(logo_path).is_file():
        mime = 'image/png' if logo_path.lower().endswith('.png') else 'image/jpeg'
        image = f'<img class="logo" alt="IT’S WRAP" src="data:{mime};base64,{base64.b64encode(Path(logo_path).read_bytes()).decode()}" />'
    else:
        image = f'<img class="logo" alt="IT’S WRAP" src="data:image/png;base64,{_LOGO_BASE64}" />'
    title = 'Oferta dla Twojej floty' if mode == 'B2B' else 'Oferta dla Twojego samochodu'
    doc = f'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>{_esc(number)} – IT’S WRAP</title><style>
:root{{--blue:#007dc5;--navy:#172d43;--ink:#131a20;--muted:#66747e}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--ink);background:#f3f6f8}}main{{max-width:1120px;margin:auto;background:white;box-shadow:0 12px 50px #1122}}header{{padding:24px 6%;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:4px solid var(--blue)}}.logo{{width:190px;max-width:100%;height:auto}}.wordmark{{font-size:30px;color:var(--blue);font-weight:900}}.wordmark b{{color:#101010}}.eyebrow{{text-transform:uppercase;letter-spacing:2px;font-size:12px;color:var(--blue);font-weight:700}}section{{padding:55px 7%}}.hero{{background:linear-gradient(110deg,#101d2a,#223e59);color:white;padding:90px 7%;border-radius:0 0 38px 38px}}.hero .eyebrow{{color:#79cbff}}h1{{font-size:clamp(34px,5.5vw,68px);line-height:1.07;max-width:850px;margin:20px 0}}h2{{font-size:clamp(26px,3vw,40px);margin:0 0 22px}}.underline{{height:3px;background:var(--blue);width:140px;margin:20px 0}}p{{line-height:1.72;max-width:780px}}.lead{{font-size:19px;color:#dceaf5}}.chip{{display:inline-block;padding:8px 12px;border:1px solid #a5bad0;border-radius:8px;margin:5px 0}}.dark{{background:#192b40;color:white}}.dark p{{color:#dce8f0}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}}.card{{border-radius:22px;background:#eff5f9;padding:28px}}.card h3{{margin-top:0}}.dark .card{{background:#29415d}}.price{{font-size:46px;font-weight:800}}.notice{{font-size:13px;color:var(--muted)}}.button{{display:inline-block;background:var(--blue);color:white;text-decoration:none;padding:17px 24px;border-radius:5px;font-weight:700}}footer{{background:#0a1725;color:white;padding:30px 7%;font-size:12px}}.preview{{position:sticky;top:0;background:#ffd98d;color:#382900;text-align:center;padding:8px;font-size:12px;z-index:3}}@media(max-width:650px){{header{{padding:15px 5%}}.grid{{grid-template-columns:1fr}}section{{padding:42px 6%}}.hero{{padding:70px 6%}}.price{{font-size:36px}}}}
</style></head><body><div class="preview">WERSJA TESTOWA · Bez autoryzacji do wysyłki klientowi · Bez publikacji online</div><main><header>{image}<small>{_esc(number)} · {_esc(mode)}</small></header><div class="hero"><span class="eyebrow">MAKE IT CHANGE · {_esc(mode)}</span><h1>{_esc(title)}</h1><p class="lead">{_esc(car)}</p><div class="underline"></div><p>Przygotowano dla: <b>{_esc(client)}</b></p><a class="button" href="#zakres">Zobacz propozycję →</a></div><section><span class="eyebrow">Indywidualna rekomendacja</span><h2>{_esc(service)}</h2><div class="underline"></div><p>{_esc(intro).replace(chr(10), '<br>') if intro else 'Wersja demonstracyjna. Tekst rekomendacji wymaga zatwierdzenia według tabeli treści ofertowych.'}</p></section><section id="zakres" class="dark"><span class="eyebrow">Co obejmuje propozycja?</span><h2>Zakres realizacji</h2><div class="grid"><div class="card"><h3>Wybrana usługa</h3><p>{_esc(service)}</p><p>{_esc(car)}</p></div><div class="card"><h3>Elementy dodatkowe</h3><ul>{additions}</ul></div></div></section><section><span class="eyebrow">Wycena</span><h2>Propozycja cenowa</h2><div class="underline"></div><div class="price">{_esc(price)}</div><p>{_esc(tax)}</p><p class="notice">Cena skopiowana z wyniku istniejącej kalkulacji; dla B2C sposób prezentacji VAT/brutto wymaga osobnego potwierdzenia. Wersja testowa nie jest ofertą handlową.</p></section><section class="dark"><h2>Porozmawiajmy o realizacji</h2><p>Ta demonstracja nie wysyła danych ani wiadomości. Docelowo pojawi się tutaj kontakt z opiekunem i akceptacja wariantu.</p></section><footer>IT’S WRAP · MAKE IT CHANGE · Dokument testowy { _esc(number) }</footer></main></body></html>'''
    return doc.encode('utf-8')
